static void handle_data(esp_mqtt_event_handle_t event) {
    // event->data är inte nollterminerad, så kopiera den till en sträng först
    char msg[128];
    int len = event->data_len < (int)sizeof(msg) - 1 ? event->data_len : (int)sizeof(msg) - 1;
    memcpy(msg, event->data, len);
    msg[len] = '\0';

    if (strstr(msg, "\"ON\"")) {
        printf("light on\n");
    } else if (strstr(msg, "\"OFF\"")) {
        printf("light off\n");
    }
}

